import sys
import xml.etree.ElementTree as ET
import requests
from requests.exceptions import RequestException

def main():
    if len(sys.argv) != 2:
        print("Usage: python endpoint_status.py <endpoints.xml>", file=sys.stderr)
        sys.exit(1)

    xml_file = sys.argv[1]
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
    except ET.ParseError as e:
        print(f"Error parsing XML file: {e}", file=sys.stderr)
        sys.exit(1)
    except FileNotFoundError:
        print(f"File not found: {xml_file}", file=sys.stderr)
        sys.exit(1)

    for endpoint in root.findall('endpoint'):
        name = endpoint.get('name')
        url = endpoint.text
        if not name or not url:
            continue

        try:
            response = requests.get(url, timeout=5, allow_redirects=False)
            print(f"{name}\t{response.status_code}")
        except RequestException:
            print(f"{name}\tERROR")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import requests
from requests.exceptions import RequestException

def main():
    if len(sys.argv) != 2:
        print("Usage: python endpoint_status.py <config_file>")
        return

    config_file = sys.argv[1]
    try:
        tree = ET.parse(config_file)
        root = tree.getroot()
    except ET.ParseError:
        print("Error parsing XML file.")
        return
    except FileNotFoundError:
        print("File not found.")
        return

    for endpoint in root.findall('endpoint'):
        name = endpoint.get('name')
        url = endpoint.text.strip() if endpoint.text else ''
        try:
            response = requests.get(url, timeout=5, allow_redirects=False)
            print(f"{name}\t{response.status_code}")
        except RequestException:
            print(f"{name}\tERROR")

if __name__ == '__main__':
    main()
